<?php require_once 'includes/db.php'; $data=$_GET['data']??date('Y-m-d');$s=$pdo->prepare("SELECT f.codigo,f.data_frete,f.status,o.identificacao origem,d.identificacao destino,t.nome transportador,GROUP_CONCAT(CONCAT(p.nome,' x',fp.quantidade) SEPARATOR ' | ') produtos FROM fretes f JOIN enderecos o ON o.id=f.origem_id JOIN enderecos d ON d.id=f.destino_id JOIN transportadores t ON t.id=f.transportador_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id WHERE f.data_frete=? GROUP BY f.id ORDER BY f.codigo");$s->execute([$data]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="fretes-'.$data.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Código','Data','Origem','Destino','Transportador','Produtos','Status'],';');foreach($s as $r)fputcsv($out,[$r['codigo'],$r['data_frete'],$r['origem'],$r['destino'],$r['transportador'],$r['produtos'],$r['status']],';');fclose($out);
